"""
Web font CSS for Platform Atlas HTML reports.

get_font_css() returns either the Google Fonts @import (network_policy=allow,
the default) or inline base64-encoded woff2 data URIs (network_policy=disallow).
Latin + latin-ext subsets only; all three families use variable-weight files so
one @font-face per file covers the full 300-800 weight range (~192 KB embedded).
"""

_GOOGLE_FONTS_IMPORT = (
    "@import url('https://fonts.googleapis.com/css2?"
    "family=Hanken+Grotesk:wght@300;400;500;600;700;800"
    "&family=Sora:wght@300;400;500;600;700;800"
    "&family=JetBrains+Mono:wght@400;500;600"
    "&display=swap');"
)

EMBEDDED_FONTS_CSS = """
/* latin-ext */
@font-face {
  font-family: 'Hanken Grotesk';
  font-style: normal;
  font-weight: 300 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}
/* latin */
@font-face {
  font-family: 'Hanken Grotesk';
  font-style: normal;
  font-weight: 300 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}
/* latin-ext */
@font-face {
  font-family: 'JetBrains Mono';
  font-style: normal;
  font-weight: 400 600;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}
/* latin */
@font-face {
  font-family: 'JetBrains Mono';
  font-style: normal;
  font-weight: 400 600;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}
/* latin-ext */
@font-face {
  font-family: 'Sora';
  font-style: normal;
  font-weight: 300 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}
/* latin */
@font-face {
  font-family: 'Sora';
  font-style: normal;
  font-weight: 300 800;
  font-display: swap;
  src: url(data:font/woff2;base64,) format('woff2');
}
"""


def get_font_css() -> str:
    """Return font CSS for the active network_policy.

    allow (default): Google Fonts CDN @import — browsers fetch only what
    they need. disallow: self-contained base64 woff2 data URIs with no
    outbound browser requests.
    """
    try:
        from platform_atlas.core.config import is_config_loaded, get_config
        if is_config_loaded() and get_config().network_policy == "disallow":
            return EMBEDDED_FONTS_CSS
    except Exception:
        pass
    return _GOOGLE_FONTS_IMPORT
